css:
:root{--ink:#17202a;--ink2:#4b5563;--blue:#2563eb;--tint:#eff4ff;--line:#dbe3f0;--soft:#f6f8fc}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:#fff;color:var(--ink);font-family:var(--page-sans),sans-serif;font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word}
a{color:inherit}
:focus-visible{outline:3px solid var(--blue);outline-offset:3px;border-radius:4px}
.top{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 20px;background:rgba(255,255,255,.94);border-bottom:1px solid var(--line)}
.brand{font-weight:700;text-decoration:none}
.top nav{display:flex;gap:16px;font-size:14px}
.top nav a{text-decoration:none;color:var(--ink2);padding:4px 0;border-bottom:2px solid transparent}
.top nav a:hover{color:var(--blue);border-color:var(--blue)}
main{display:block;max-width:680px;margin:0 auto;padding:0 20px}
.hero{display:block;padding:72px 0 56px}
.label{margin:0 0 12px;font-family:var(--page-mono),monospace;font-size:13px;letter-spacing:.02em;color:var(--blue)}
h1{margin:0 0 24px;font-family:var(--page-display),var(--page-sans),sans-serif;font-size:clamp(32px,7vw,48px);line-height:1.2;letter-spacing:-.02em;font-weight:700}
.lead{margin:0 0 32px;font-size:17px;color:var(--ink2)}
.proof{display:grid;gap:0;margin:0;padding:0;border:1px solid var(--line);border-radius:12px;background:var(--soft);width:min(100%,680px)}
.proof div{display:flex;justify-content:space-between;align-items:baseline;gap:16px;padding:14px 18px;border-top:1px solid var(--line)}
.proof div:first-child{border-top:0}
.proof dt{font-size:14px;color:var(--ink2)}
.proof dd{margin:0;font-family:var(--page-mono),monospace;font-weight:700;color:var(--blue);text-align:right}
.proof dd span{color:var(--ink2)}
.hint{font-size:13px;color:var(--ink2);margin:12px 0 0;line-height:1.6}
.sec{display:block;padding:56px 0;border-top:1px solid var(--line)}
h2{margin:0 0 12px;font-size:clamp(24px,5vw,30px);line-height:1.35;letter-spacing:-.01em}
.take{margin:0 0 28px;font-size:17px;font-weight:600;color:var(--blue)}
h3{margin:28px 0 8px;font-size:16px}
.tag{display:inline-block;padding:2px 10px;border-radius:999px;background:var(--tint);color:var(--blue);font-size:13px;font-weight:700}
p{margin:0 0 12px}
.flow{margin:24px 0;padding:0;display:block}
.lane{display:block;border-radius:12px;padding:16px 18px;border:1px solid var(--line)}
.lane.before{background:var(--soft)}
.lane.after{background:var(--tint);border-color:var(--blue)}
.lane-name{display:block;font-family:var(--page-mono),monospace;font-size:12px;color:var(--ink2);margin-bottom:6px}
.lane.after .lane-name{color:var(--blue)}
.lane ol{margin:0;padding-left:20px;font-size:15px}
.arrow{text-align:center;color:var(--blue);font-size:20px;line-height:1.6}
.flow figcaption,.chart figcaption{font-size:13px;color:var(--ink2);margin-top:10px}
.bars{display:block;margin:12px 0 0}
.bar-row{display:block;margin-bottom:18px}
.bar-name{display:block;font-size:14px;font-weight:600;margin-bottom:6px}
.track{position:relative;display:flex;align-items:center;gap:10px;margin-bottom:6px}
.fill{display:block;height:22px;border-radius:4px;min-width:6px;transform-origin:left;animation:grow .8s ease-out both}
.fill.old{background:#c7d2e4}
.fill.new{background:var(--blue)}
.val{font-family:var(--page-mono),monospace;font-size:13px;font-weight:700;white-space:nowrap}
.track{flex-wrap:nowrap}
@keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.more{margin-top:20px;border:1px solid var(--line);border-radius:10px;padding:0}
.more summary{cursor:pointer;padding:12px 16px;font-weight:600;font-size:15px}
.more summary:hover{color:var(--blue)}
.more ul{margin:0;padding:0 16px 14px 36px;font-size:15px;color:var(--ink2)}
.steps{list-style:none;margin:0 0 28px;padding:0;counter-reset:s;border-left:2px solid var(--line)}
.steps li{counter-increment:s;position:relative;padding:0 0 18px 24px}
.steps li::before{content:counter(s);position:absolute;left:-13px;top:0;width:24px;height:24px;border-radius:50%;background:var(--blue);color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center}
.steps b{display:block;font-size:15px}
.steps span{display:block;color:var(--ink2);font-size:15px}
.chart{margin:0;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--soft);display:block}
.chart figcaption{margin:0 0 10px;font-weight:600;color:var(--ink)}
.stack{margin:0;display:block;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.stack div{display:grid;grid-template-columns:96px 1fr;gap:16px;padding:16px 18px;border-top:1px solid var(--line)}
.stack div:first-child{border-top:0}
.stack div:hover{background:var(--soft)}
.stack dt{font-family:var(--page-mono),monospace;font-size:13px;color:var(--blue);padding-top:3px}
.stack dd{margin:0;font-size:15px}
.stack b{display:inline-block;margin-right:6px;color:var(--ink)}
.foot{border-top:1px solid var(--line);padding:28px 20px;text-align:center;font-size:13px;color:var(--ink2)}
.foot p{margin:0}
@media (max-width:560px){.top nav{gap:10px;font-size:13px}.hero{padding:48px 0 40px}.proof div{flex-direction:column;gap:2px}.proof dd{text-align:left}.stack div{grid-template-columns:1fr;gap:4px}.sec{padding:44px 0}}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.fill{animation:none}}
